package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the edited claim once every rule has passed and it is saved. */
public class AuditClaimEdited {
    public void audit(@Val Claim claim, @RequestParam(value = "user", required = false) String user,
            PersonRepository people, Audit audit) {
        Person person = people.findById(claim.getSheetId(), claim.getPersonId());
        audit.record("CLAIM_EDITED sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate());
    }
}
EOF
cat > /tmp/ed2.js <<'EOF'
const fs=require('fs');
const R='resources/officefloor/rest/api/sheets/{sheetId}/';
function ed(f,prev,cls){const p=R+f;let s=fs.readFileSync(p,'utf8');
 const a=`  class: net.officefloor.hq.app.${prev}\n  govern: [ transaction ]\n  next: respond\n`;
 if(!s.includes(a))throw new Error(p);
 s=s.replace(a,`  class: net.officefloor.hq.app.${prev}\n  govern: [ transaction ]\n  next: audit\naudit:\n  class: net.officefloor.hq.app.${cls}\n  govern: [ transaction ]\n  next: respond\n`);
 s=s.replace(/^# /,'# The audit line is written last, once every rule has passed, so a refused change writes none.\n# ');
 fs.writeFileSync(p,s);}
ed('people.POST.yml','person.CreatePerson','person.AuditPersonAdded');
ed('people/{personId}.PUT.yml','person.SavePerson','person.AuditPersonEdited');
ed('claims/{claimId}.PUT.yml','claim.SaveClaim','claim.AuditClaimEdited');
ed('people/{personId}/claims.POST.yml','claim.CreateClaim','claim.AuditClaimAdded');
EOF
node /tmp/ed2.js && cat "resources/officefloor/rest/api/sheets/{sheetId}/people.POST.yml"

